namespace{void Register(ReplayRuntime*r,const ReplayRuntimeOps*o){r->update_task=o->register_task(o->context,11,0,r);r->draw_task=o->register_task(o->context,27,1,r);r->aux_task=o->register_task(o->context,5,2,r);}void ToSnapshot(ReplayRunSnapshot&s,const ReplayRuntimeGlobals&g){s.stage=g.stage;s.route=g.route;s.score=g.score;s.power=g.power;s.lives=g.lives;s.bombs=g.bombs;s.continues=g.continues;s.graze=g.graze;s.gauge=g.gauge;s.flags=g.flags;}void FromSnapshot(ReplayRuntimeGlobals&g,const ReplayRunSnapshot&s){g.stage=s.stage;g.route=s.route;g.score=s.score;g.power=s.power;g.lives=s.lives;g.bombs=s.bombs;g.continues=s.continues;g.graze=s.graze;g.gauge=s.gauge;g.flags=s.flags;}}
// 0x00428F60 - construct a recording runtime or restore a loaded replay.
int ReplayRuntime_Bootstrap(ReplayRuntime*r,int mode,const char*path,ReplayRuntimeGlobals*g,const ReplayRuntimeOps*o){r->mode=mode;if(mode==0){r->magic=0x72303174u;r->version=5;r->capacity=0x100;std::memset(&r->snapshot,0,sizeof(r->snapshot));for(int i=0;i<8;++i)std::memset(&r->stages[i],0,sizeof(r->stages[i]));ToSnapshot(r->snapshot,*g);if(o->copy_profile_out)o->copy_profile_out(o->context,&r->snapshot);r->stages[g->stage]=r->snapshot;r->stages[g->stage].stage=g->stage;Register(r,o);r->active_stage=g->stage;return 0;}if(mode==1){if(!o->load(o->context,path,r))return -1;FromSnapshot(*g,r->snapshot);if(o->copy_profile_in)o->copy_profile_in(o->context,&r->snapshot);Register(r,o);r->active_stage=-1;return 0;}if(mode==2)return o->load(o->context,path,r)?-1:0;return 0;}
